window.kbPageData["views/entry/k-29e2ab3a476bb649"] = {"key":"entry/k-29e2ab3a476bb649","state":{"route":"entry/k-29e2ab3a476bb649"},"node":{"id":"k-29e2ab3a476bb649","mode":"k","title":"回顾成就","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["事实与事件"],"出处性质":["公报解读正文"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["二十届五中全会"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"党的二十届五中全会","slug":"6a94c2ad76dd"}],"directorySummary":"全会高度评价新时代全面从严治党取得的伟大成就。一致认为，以习近平同志为核心\n的党中央以巨大的政治勇气和强烈的责任担当，直面一度出现党的领导弱化虚化淡化、管\n党治党不严不实不力、党内一些问题触目惊心的严峻现实，坚定不移全面从严治党，刀刃\n向内、重典治乱，持续解决突出问题，从根本上扭转了管党治党宽松软状…","sources":[{"id":"a1b63355863aa1ad","label":"回顾成就","topic":"二十届五中全会","category":"时政","text":"全会高度评价新时代全面从严治党取得的伟大成就。一致认为，以习近平同志为核心\n的党中央以巨大的政治勇气和强烈的责任担当，直面一度出现党的领导弱化虚化淡化、管\n党治党不严不实不力、党内一些问题触目惊心的严峻现实，坚定不移全面从严治党，刀刃\n向内、重典治乱，持续解决突出问题，从根本上扭转了管党治党宽松软状况，刹住了一些\n长期没有刹住的歪风，纠治了一些多年未除的顽瘴痼疾，消除了党、国家、军队内部存在\n的严重隐患，党在革命性锻造中更加坚强有力。新时代全面从严治党开辟了百年大党自我\n革命新境界，推动党和国家事业取得历史性成就、发生历史性变革，党和人民赢得强党强\n国的历史主动。\n全会指出，在新时代管党治党、兴党强党伟大实践中，以习近平同志为核心的党中央\n围绕建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党的重\n大时代课题，提出一系列新理念新思想新战略，形成习近平党建思想①。这一思想丰富和\n发展了马克思主义建党学说，是坚持把马克思主义基本原理同中国具体实际相结合、同中\n华优秀传统文化相结合推进党的理论创新的重大成果，是党和人民实践经验和集体智慧的\n结晶，是习近平新时代中国特色社会主义思想的重要组成部分，为深入推进新时代党的建\n设新的伟大工程提供了根本遵循和行动指南。","source":{"doc":"41195a191a57c1c36332","first":7,"last":7,"page":7,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"},{"id":"291933e712394d83","label":"回顾成就","topic":"二十届五中全会","category":"时政","text":"全会回顾党 100 多年来的奋斗历程，指出中国共产党能够从胜利走向胜利，就在于胸\n怀共产主义远大理想，立志于中华民族千秋伟业，坚持为中国人民谋幸福、为中华民族谋\n复兴①，在各个历史时期都高度重视管党治党，勇于坚持真理、修正错误，在依靠自身力量\n和人民支持解决自身问题中不断强大，成为党和人民事业的坚强领导核心。在革命、建\n设、改革中先后把党的建设②作为伟大工程、新的伟大工程，党的十八大以来深入推进新\n时代党的建设新的伟大工程，找到“让人民来监督政府”和“自我革命”③两个跳出治乱\n兴衰历史周期率的答案，这是中国共产党的独特创造，永载马克思主义政党建设史册。","source":{"doc":"41195a191a57c1c36332","first":6,"last":6,"page":6,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"},{"id":"afab433c71329e45","label":"回顾成就","topic":"二十届五中全会","category":"时政","text":"一、回顾成就\n全会充分肯定党的二十届四中全会以来中央政治局的工作。一致认为，中央政治局认\n真落实党的二十大和二十届历次全会精神，坚持稳中求进工作总基调，完整准确全面贯彻\n新发展理念①，统筹推进“五位一体”总体布局②，协调推进“四个全面”战略布局③，统\n筹国内国际两个大局④，统筹发展和安全，扎实推动经济高质量发展，推进社会主义民主法\n治建设，做好宣传思想文化工作，抓好民生保障和生态文明建设，维护国家安全和社会稳\n定，纵深推进全面从严治党，加强国防和军队现代化建设⑤，做好港澳工作和对台工作，推\n进中国特色大国外交，“十四五”圆满收官，“十五五”⑥开局良好，党和国家事业取得新\n进展新成效。开展树立和践行正确政绩观学习教育⑦，隆重庆祝中国共产党成立 105 周年\n⑧，进一步凝聚起全党全国各族人民团结奋进的强大力量。","source":{"doc":"41195a191a57c1c36332","first":3,"last":3,"page":3,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-29e2ab3a476bb649":[]}};
